function tests=testAdaptationReflectance
% Independent references, physical scaling invariants and refusal cases.
tests=functiontests(localfunctions);
end

function setupOnce(testCase)
colormeasuretest.setupPaths(testCase);
end
function testBradfordPublishedExample(t)
% Colour 0.4.7 chromatic_adaptation_VonKries documentation, Bradford example.
% Rounded published output, not generated by this implementation.
source=[0.95045593 1 1.08905775];destination=[0.96429568 1 0.82510460];
[actual,meta]=colormeasure.colorimetry.adaptXYZ([.20654008 .12197225 .05136952],source,destination);
verifyEqual(t,actual,[.2166600 .1260477 .0385506],'AbsTol',1e-7);
verifyEqual(t,meta.method,'Linear Bradford');verifyEqual(t,meta.degreeOfAdaptation,1);
verifyEqual(t,meta.sourceWhiteXYZ,source);verifyEqual(t,meta.destinationWhiteXYZ,destination);
end
function testBradfordIdentityWhiteMappingAndBrightness(t)
source=[.95047 1 1.08883];destination=[.96422 1 .82521];
xyz=[10 20 30;0 0 0;-1 .5 2];
verifyEqual(t,colormeasure.colorimetry.adaptXYZ(xyz,source,source),xyz);
[mapped,meta]=colormeasure.colorimetry.adaptXYZ(source*203,source*100,destination*7);
verifyEqual(t,mapped,destination*203,'AbsTol',1e-12);
adapted=colormeasure.colorimetry.adaptXYZ(xyz,source,destination);
verifyEqual(t,colormeasure.colorimetry.adaptXYZ(xyz*100,source*7,destination*.01),100*adapted,'AbsTol',2e-12);
verifyEqual(t,colormeasure.colorimetry.adaptXYZ(adapted,destination,source),xyz,'AbsTol',2e-14);
verifyEqual(t,meta.sourceWhiteY1,source,'AbsTol',eps);
verifyLessThan(t,adapted(3,1),0);
end
function testBradfordShapesAndInvalidWhites(t)
s=[.95 1 1.09];d=[.96 1 .83];xyz=[1 2 3;4 5 6];
verifyEqual(t,colormeasure.colorimetry.adaptXYZ(xyz.',s,d),colormeasure.colorimetry.adaptXYZ(xyz,s,d).');
verifyClass(t,colormeasure.colorimetry.adaptXYZ(single(xyz),s,d),'double');
for bad={zeros(1,3),[1 0 1],[NaN 1 1],[1 1 Inf],[1 1 1i],ones(3,1),[10 .01 .01]}
    verifyError(t,@()colormeasure.colorimetry.adaptXYZ(xyz,bad{1},d),'colormeasure:Colorimetry:InvalidWhite');
end
verifyError(t,@()colormeasure.colorimetry.adaptXYZ([1 NaN 3],s,d),'colormeasure:Colorimetry:InvalidInput');
verifyError(t,@()colormeasure.colorimetry.adaptXYZ(xyz,[realmax realmin 1],d),'colormeasure:Colorimetry:NumericRange');
end
function testOfficialIlluminantBytesAndMetadata(t)
root=colormeasuretest.projectRoot();
stems={'CIE_std_illum_D50','CIE_std_illum_D65','CIE_std_illum_A_1nm'};
suffix={'.csv_metadata.json','.csv_metadata_v2.json','.csv_metadata_v2.json'};
names={'D50','D65','A'};
for index=1:3
    filename=fullfile(root,'resources','colorimetry',[stems{index} '.csv']);
    hash=colormeasuretest.fileSha256(filename);
    metadata=jsondecode(fileread(fullfile(root,'resources','colorimetry',[stems{index} suffix{index}])));
    selected=strcmp({metadata.checksums.hashMethod},'sha256');
    verifyEqual(t,hash,metadata.checksums(selected).checksum);
    [spd,provenance]=colormeasure.colorimetry.illuminantSpectrum(names{index},(300:830)');
    table=readmatrix(filename);
    verifyEqual(t,spd,table(:,2));verifyEqual(t,provenance.sourceSHA256,hash);
    verifyEqual(t,provenance.license,'CC BY-SA 4.0');
end
end
function testIlluminantInterpolationAndNoExtrapolation(t)
for name={'D50','D65','A'}
    exact=colormeasure.colorimetry.illuminantSpectrum(name{1},[500;501;502]);
    [fractional,meta]=colormeasure.colorimetry.illuminantSpectrum(name{1},[500.5;501.5]);
    verifyEqual(t,fractional,(exact(1:2)+exact(2:3))/2,'AbsTol',2e-14);
    verifyEqual(t,meta.interpolation,'Linear table interpolation');
    verifyEqual(t,meta.extrapolation,'None');
end
verifyError(t,@()colormeasure.colorimetry.illuminantSpectrum('D55',[500;501]),'colormeasure:Colorimetry:WhiteIlluminant');
verifyError(t,@()colormeasure.colorimetry.illuminantSpectrum('D65',[299;300]),'colormeasure:Colorimetry:IlluminantDomain');
verifyError(t,@()colormeasure.colorimetry.illuminantSpectrum('D65',[830;831]),'colormeasure:Colorimetry:IlluminantDomain');
verifyError(t,@()colormeasure.colorimetry.illuminantSpectrum('D65',[500;501;503]),'colormeasure:Colorimetry:Wavelength');
end
function testReferenceRatioCharacterizedPlateAndSignedEstimates(t)
w=(400:100:700)';reference=[1;2;4;8];plate=[.9;.92;.94;.96];
sample=[reference*.5 reference*1.5 -reference*.1];
[actual,meta]=colormeasure.colorimetry.reflectanceFromReference(sample,reference,plate,w);
verifyEqual(t,actual,plate.*[.5 1.5 -.1],'AbsTol',eps);
verifyTrue(t,meta.hasNegativeEstimates);verifyTrue(t,meta.hasEstimatesAboveOne);
verifyEqual(t,meta.referenceReflectance,plate);
verifyEqual(t,colormeasure.colorimetry.reflectanceFromReference(sample.',reference.',plate.',w),actual);
verifyEqual(t,colormeasure.colorimetry.reflectanceFromReference(sample*1e-100,reference*1e-100,plate,w),actual,'AbsTol',eps);
end
function testWeakReferenceAndInvalidCharacterizationRefused(t)
w=(400:100:700)';sample=ones(4,1);plate=.95*ones(4,1);
for bad={[0;1;1;1],[-1;1;1;1],[1e-10;1;1;1],zeros(4,1)}
    verifyError(t,@()colormeasure.colorimetry.reflectanceFromReference(sample,bad{1},plate,w),'colormeasure:Colorimetry:WeakReference');
end
verifyError(t,@()colormeasure.colorimetry.reflectanceFromReference(sample,ones(3,1),plate,w),'colormeasure:Colorimetry:SpectrumShape');
verifyError(t,@()colormeasure.colorimetry.reflectanceFromReference(sample,ones(4,1),ones(3,1),w),'colormeasure:Colorimetry:SpectrumShape');
verifyError(t,@()colormeasure.colorimetry.reflectanceFromReference(sample,ones(4,1),[0;1;1;1],w),'colormeasure:Colorimetry:ReferenceReflectance');
verifyError(t,@()colormeasure.colorimetry.reflectanceFromReference(sample,ones(4,1),plate,[400;500;600;701]),'colormeasure:Colorimetry:Wavelength');
verifyError(t,@()colormeasure.colorimetry.reflectanceFromReference(sample,[NaN;1;1;1],plate,w),'colormeasure:Colorimetry:Spectrum');
end
function testReflectancePerfectDiffuserAndGray(t)
w=(360:830)';r=[ones(size(w)) .18*ones(size(w)) zeros(size(w))];
for name={'D50','D65','A'}
    [xyz,white,meta]=colormeasure.colorimetry.reflectanceXYZ(r,w,name{1});
    known=colormeasure.colorimetry.illuminantWhite(name{1},100);
    verifyEqual(t,white,known.XYZ,'AbsTol',4e-12);
    verifyEqual(t,xyz(1,:),white,'AbsTol',4e-12);
    verifyEqual(t,xyz(2,:),.18*white,'AbsTol',4e-12);
    verifyEqual(t,xyz(:,2),[100;18;0],'AbsTol',3e-12);
    verifyFalse(t,meta.limitedRange);verifyEqual(t,meta.whiteXYZ,white);
end
end
function testReflectanceIntegrationIndependentBinWeightsAndRange(t)
w=[500;550;600];[cmf,native]=colormeasure.colorimetry.observer();selected=cmf(ismember(native,w),:);
illuminant=[1;2;3];r=[0;1;0];
% Direct one-bin expected value from table rows and scalar normalization.
denominator=selected(1,2)+2*selected(2,2)+3*selected(3,2);
expected=200*selected(2,:)/denominator;
[xyz,white,meta]=colormeasure.colorimetry.reflectanceXYZ(r,w,illuminant);
verifyEqual(t,xyz,expected,'AbsTol',2e-14);verifyEqual(t,white(2),100,'AbsTol',1e-13);
verifyTrue(t,meta.limitedRange);verifyEqual(t,meta.wavelengthRangeNm,[500 600]);
verifyEqual(t,meta.illuminantSPD,illuminant);
verifyEqual(t,colormeasure.colorimetry.reflectanceXYZ(r,w,illuminant*1e300),xyz,'AbsTol',3e-14);
verifyEqual(t,colormeasure.colorimetry.reflectanceXYZ(r,w,illuminant*1e-300),xyz,'AbsTol',3e-14);
end
function testReflectanceOrientationAndSignedFactorsRetained(t)
w=(380:4:780)';r=[-.05*ones(size(w)) 1.2*ones(size(w))];
[xyz,white,meta]=colormeasure.colorimetry.reflectanceXYZ(r,w,'D65');
verifyEqual(t,xyz,[-.05;1.2]*white,'AbsTol',4e-13);
verifyTrue(t,meta.hasNegativeReflectance);verifyTrue(t,meta.hasReflectanceAboveOne);
verifyEqual(t,colormeasure.colorimetry.reflectanceXYZ(r.',w,'D65'),xyz);
verifyTrue(t,meta.limitedRange);verifyEqual(t,meta.wavelengthStepNm,4);
end
function testReflectanceInvalidInputsAndRangeRefused(t)
w=(380:4:780)';r=ones(size(w));
verifyError(t,@()colormeasure.colorimetry.reflectanceXYZ(r,w,zeros(size(w))),'colormeasure:Colorimetry:IlluminantSpectrum');
verifyError(t,@()colormeasure.colorimetry.reflectanceXYZ(r,w,-ones(size(w))),'colormeasure:Colorimetry:IlluminantSpectrum');
verifyError(t,@()colormeasure.colorimetry.reflectanceXYZ(r,w,ones(10,1)),'colormeasure:Colorimetry:SpectrumShape');
verifyError(t,@()colormeasure.colorimetry.reflectanceXYZ(r,w,repmat(r,1,2)),'colormeasure:Colorimetry:SpectrumShape');
verifyError(t,@()colormeasure.colorimetry.reflectanceXYZ(ones(2,1),[359;360],'D65'),'colormeasure:Colorimetry:ObserverDomain');
verifyError(t,@()colormeasure.colorimetry.reflectanceXYZ(ones(2,1),[830;831],'D65'),'colormeasure:Colorimetry:ObserverDomain');
verifyError(t,@()colormeasure.colorimetry.reflectanceXYZ(NaN(size(r)),w,'D65'),'colormeasure:Colorimetry:Spectrum');
verifyError(t,@()colormeasure.colorimetry.reflectanceXYZ(realmax*ones(size(r)),w,'D65'),'colormeasure:Colorimetry:NumericRange');
end
